python3 -c "
import json
with open('/app/resources/treasury_bulletin_1980_02.json') as f:
    data = json.load(f)

# Search for currency and coin in all content
def search_elements(elements, search_term):
    results = []
    for el in elements:
        if isinstance(el, dict):
            if 'content' in el and el['content'] and search_term.lower() in str(el['content']).lower():
                results.append(el)
            if 'elements' in el:
                results.extend(search_elements(el['elements'], search_term))
    return results

results = search_elements(data['document']['elements'], 'Currency and Coin')
print(f'Found {len(results)} elements')
for r in results:
    print('---')
    print(r.get('content', '')[:500])
"

